import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Zugriff auf geteilte Inhalte","description":"Zugriffsbeschränkungen für Formular-, Ansichts- und Portal-Links in ApptiveGrid.","frontmatter":{"title":"Zugriff auf geteilte Inhalte","description":"Zugriffsbeschränkungen für Formular-, Ansichts- und Portal-Links in ApptiveGrid."},"headers":[],"relativePath":"zusammenarbeit/zugriff-beschraenken.md","filePath":"zusammenarbeit/zugriff-beschraenken.md","lastUpdated":1786014774000}'),a={name:"zusammenarbeit/zugriff-beschraenken.md"};function s(l,e,d,o,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="zugriff-auf-geteilte-inhalte" tabindex="-1">Zugriff auf geteilte Inhalte <a class="header-anchor" href="#zugriff-auf-geteilte-inhalte" aria-label="Permalink to &quot;Zugriff auf geteilte Inhalte&quot;">​</a></h1><p>Jeder geteilte Link in ApptiveGrid ist <strong>standardmäßig für jede Person mit dem Link erreichbar</strong>. Wer den Zugriff einschränken will, muss das ausdrücklich einstellen.</p><div class="danger custom-block"><p class="custom-block-title">Der wichtigste Punkt zuerst</p><p>Ein Freigabelink ist nicht erratbar, aber ungeschützt. Wird er weitergeleitet, in einen Chat kopiert oder in einer E-Mail zitiert, funktioniert er dort weiter.</p><p>Behandeln Sie einen unbeschränkten Link wie eine Veröffentlichung.</p></div><h2 id="zwei-unterschiedliche-modelle" tabindex="-1">Zwei unterschiedliche Modelle <a class="header-anchor" href="#zwei-unterschiedliche-modelle" aria-label="Permalink to &quot;Zwei unterschiedliche Modelle&quot;">​</a></h2><p>ApptiveGrid kennt <strong>zwei getrennte Beschränkungsmodelle</strong>. Welches gilt, hängt davon ab, was Sie teilen. Das ist die häufigste Verwechslung in diesem Bereich.</p><table tabindex="0"><thead><tr><th>Sie teilen …</th><th>Modell</th><th>Dialog</th></tr></thead><tbody><tr><td><strong>Formular</strong></td><td>Wer darf zugreifen — nach Konto</td><td><em>Zugriffsbeschränkungen festlegen</em></td></tr><tr><td><strong>Ansicht</strong> oder <strong>Seite/Portal</strong></td><td>Benutzername und Passwort</td><td><em>Zugriffsberechtigungen einstellen</em></td></tr></tbody></table><p>Die beiden Modelle lassen sich <strong>nicht mischen</strong>. Ein Formularlink kennt kein Passwort, ein Ansichtslink keine Kontoprüfung.</p><hr><h2 id="formulare-zugriff-nach-konto" tabindex="-1">Formulare: Zugriff nach Konto <a class="header-anchor" href="#formulare-zugriff-nach-konto" aria-label="Permalink to &quot;Formulare: Zugriff nach Konto&quot;">​</a></h2><p>Im Freigabedialog eines Formulars führt <strong>Beschränkungen festlegen</strong> zum Dialog <em>Zugriffsbeschränkungen festlegen</em> mit der Frage <em>Legen Sie fest, wer über diesen Link auf das Formular zugreifen darf.</em></p><p>Drei Stufen:</p><h3 id="jeder" tabindex="-1">Jeder <a class="header-anchor" href="#jeder" aria-label="Permalink to &quot;Jeder&quot;">​</a></h3><blockquote><p><em>Jeder mit diesem Link kann darauf zugreifen.</em></p></blockquote><p>Keine Anmeldung nötig. Die Voreinstellung.</p><p><strong>Geeignet für:</strong> öffentliche Anmeldungen, Kontaktformulare, Umfragen, Rückmeldungen von Kunden.</p><h3 id="jeder-registrierte-benutzer" tabindex="-1">Jeder registrierte Benutzer <a class="header-anchor" href="#jeder-registrierte-benutzer" aria-label="Permalink to &quot;Jeder registrierte Benutzer&quot;">​</a></h3><blockquote><p><em>Nur registrierte Benutzer können mit diesem Link darauf zugreifen.</em></p></blockquote><p>Die Person muss ein ApptiveGrid-Konto haben und angemeldet sein — aber <strong>nicht</strong> Mitglied Ihres Space.</p><p><strong>Geeignet für:</strong> Formulare, bei denen Sie eine nachvollziehbare Identität brauchen, die Ausfüllenden aber nicht zum Space gehören.</p><div class="warning custom-block"><p class="custom-block-title">Das ist eine niedrige Hürde</p><p>Ein ApptiveGrid-Konto kann sich jede Person anlegen. Diese Stufe stellt sicher, dass jemand <em>angemeldet</em> ist — nicht, dass es die <em>richtige</em> Person ist. Für vertrauliche Daten reicht sie nicht.</p></div><h3 id="jeder-aus-diesem-space" tabindex="-1">Jeder aus diesem Space <a class="header-anchor" href="#jeder-aus-diesem-space" aria-label="Permalink to &quot;Jeder aus diesem Space&quot;">​</a></h3><blockquote><p><em>Nur wer zu diesem Space eingeladen wurde, kann darauf zugreifen.</em></p></blockquote><p>Die strengste Stufe. Nur Personen mit einer Rolle in diesem Space.</p><p><strong>Geeignet für:</strong> interne Formulare — Urlaubsanträge, Störungsmeldungen, interne Erfassung.</p><div class="tip custom-block"><p class="custom-block-title">Jede Rolle genügt</p><p>Auch die Rolle <em>Ansehen</em> reicht aus, um ein so beschränktes Formular auszufüllen. Sie müssen niemandem Bearbeitungsrechte geben, nur damit er ein Formular absenden kann — und verbrauchen damit auch keinen <a href="/docs/zusammenarbeit/sitzplaetze">Sitzplatz</a>.</p></div><hr><h2 id="ansichten-und-portale-benutzername-und-passwort" tabindex="-1">Ansichten und Portale: Benutzername und Passwort <a class="header-anchor" href="#ansichten-und-portale-benutzername-und-passwort" aria-label="Permalink to &quot;Ansichten und Portale: Benutzername und Passwort&quot;">​</a></h2><p>Beim Teilen einer Ansicht oder beim Veröffentlichen einer Seite führt <strong>Beschränkungen festlegen</strong> zum Dialog <em>Zugriffsberechtigungen einstellen</em> mit dem Text <em>Legen Sie fest, wer Zugriff hat</em>.</p><p>Zwei Stufen:</p><h3 id="alle" tabindex="-1">Alle <a class="header-anchor" href="#alle" aria-label="Permalink to &quot;Alle&quot;">​</a></h3><blockquote><p><em>Jede Person mit dem Link kann zugreifen</em></p></blockquote><p>Die Voreinstellung. Kein Schutz über den Link hinaus.</p><h3 id="mit-anmeldeinformationen" tabindex="-1">Mit Anmeldeinformationen <a class="header-anchor" href="#mit-anmeldeinformationen" aria-label="Permalink to &quot;Mit Anmeldeinformationen&quot;">​</a></h3><blockquote><p><em>Zugriff nur mit Benutzername und Passwort</em></p></blockquote><p>Sie vergeben ein <strong>Benutzername</strong>/<strong>Passwort</strong>-Paar. Beim Öffnen erscheint eine Anmeldemaske.</p><p>Diese Zugangsdaten haben <strong>nichts mit ApptiveGrid-Konten zu tun</strong>. Es ist ein eigenständiges Paar, das nur für diesen Link gilt. Die Empfänger brauchen kein Konto.</p><div class="danger custom-block"><p class="custom-block-title">Zugangsdaten sind nur einmal sichtbar</p><p>Nach dem Speichern bestätigt ApptiveGrid mit <em>Berechtigungen aktualisiert</em> und weist ausdrücklich darauf hin:</p><blockquote><p><em>Aus Sicherheitsgründen ist es nicht möglich, den Benutzernamen und das Passwort später einzusehen. Sie können diese jedoch jederzeit neu setzen.</em></p></blockquote><p><strong>Notieren Sie die Zugangsdaten sofort an sicherer Stelle.</strong> Gehen sie verloren, müssen Sie neue vergeben und allen Empfängern erneut zuschicken.</p></div><div class="tip custom-block"><p class="custom-block-title">Ein Passwort je Empfängerkreis</p><p>Legen Sie über <em>Link hinzufügen</em> mehrere Links auf dieselbe Ansicht an und geben Sie jedem eigene Zugangsdaten. So können Sie den Zugang einer einzelnen Gruppe entziehen, ohne allen anderen ein neues Passwort schicken zu müssen.</p></div><hr><h2 id="was-der-filter-einer-ansicht-leistet-—-und-was-nicht" tabindex="-1">Was der Filter einer Ansicht leistet — und was nicht <a class="header-anchor" href="#was-der-filter-einer-ansicht-leistet-—-und-was-nicht" aria-label="Permalink to &quot;Was der Filter einer Ansicht leistet — und was nicht&quot;">​</a></h2><p>Beim Teilen einer Ansicht sehen Empfänger nur, was in dieser Ansicht sichtbar ist. Filter und ausgeblendete Spalten wirken also mit.</p><div class="warning custom-block"><p class="custom-block-title">Filter sind Sichtschutz, kein Zugriffsschutz</p><p>Verlassen Sie sich bei wirklich vertraulichen Daten nicht allein auf Filter und ausgeblendete Spalten. Kombinieren Sie sie mit einer Zugriffsbeschränkung.</p><p>Für echte Trennung ist die sauberste Lösung, sensible Daten gar nicht erst in dasselbe Grid zu legen.</p></div><hr><h2 id="die-richtige-stufe-wahlen" tabindex="-1">Die richtige Stufe wählen <a class="header-anchor" href="#die-richtige-stufe-wahlen" aria-label="Permalink to &quot;Die richtige Stufe wählen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Empfehlung</th></tr></thead><tbody><tr><td>Öffentliches Anmeldeformular</td><td>Formular, <strong>Jeder</strong></td></tr><tr><td>Kundenrückmeldung per QR-Code</td><td>Formular, <strong>Jeder</strong></td></tr><tr><td>Internes Formular fürs Team</td><td>Formular, <strong>Jeder aus diesem Space</strong></td></tr><tr><td>Statusübersicht für einen Kunden</td><td>Ansicht, <strong>Mit Anmeldeinformationen</strong></td></tr><tr><td>Öffentliches Portal</td><td>Seite, <strong>Alle</strong></td></tr><tr><td>Portal nur für Partner</td><td>Seite, <strong>Mit Anmeldeinformationen</strong></td></tr><tr><td>Personenbezogene oder vertrauliche Daten</td><td>Nicht per Link teilen — Personen in den Space <a href="/docs/zusammenarbeit/personen-einladen">einladen</a></td></tr></tbody></table><h2 id="regelmaßig-prufen" tabindex="-1">Regelmäßig prüfen <a class="header-anchor" href="#regelmaßig-prufen" aria-label="Permalink to &quot;Regelmäßig prüfen&quot;">​</a></h2><p>Geteilte Links geraten in Vergessenheit. Die Seite <a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a> listet <strong>alle</strong> externen Zugänge eines Space an einer Stelle: Formularlinks, Ansichtslinks, Portale, Flow-Starts und Einladungen.</p><div class="tip custom-block"><p class="custom-block-title">In die Routine aufnehmen</p><p>Sehen Sie diese Liste in regelmäßigen Abständen durch und entfernen Sie, was nicht mehr gebraucht wird — besonders nach abgeschlossenen Projekten, ausgelaufenen Kampagnen und Personalwechseln.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a></li><li><a href="/docs/zusammenarbeit/personen-einladen">Personen einladen</a></li><li><a href="/docs/zusammenarbeit/rollen">Rollen</a></li><li><a href="/docs/formulare/formular-teilen">Formular teilen</a></li></ul>',50)])])}const m=n(a,[["render",s]]);export{g as __pageData,m as default};
